mapper.select:
select
from collect_interface_config where is_deleted = 0
order by id desc limit #{pageSize} offset #{offset}

select task_id, interface_id as id, coalesce(sum(collection_count), 0) as data_packet_count from collect_interface_statistics where 1 = 1
and task_id = #{taskId}
and interface_id in
#{interfaceId}
and 1 = 0
group by task_id, interface_id

select count(1)
from collect_interface_config
where transfer_type = #{transferType}
  and host = #{host}
  and port = #{port}


        and multicast_ip = #{multicastIp}


        and multicast_ip is null


  and enabled = 1
  and is_deleted = 0

    and id != #{excludeId}
